import{G as e,W as t,n,rt as r}from"./chunks/framework.DdpGKlXJ.js";var i=JSON.parse(`{"title":"ScrollbarManager Documentation","description":"","frontmatter":{},"headers":[],"relativePath":"scrollbar-manager.md","filePath":"scrollbar-manager.md"}`),a={name:`scrollbar-manager.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="scrollbarmanager-documentation" tabindex="-1">ScrollbarManager Documentation <a class="header-anchor" href="#scrollbarmanager-documentation" aria-label="Permalink to “ScrollbarManager Documentation”">​</a></h1><p>The <code>ScrollbarManager</code> class is an independent and intelligent utility designed to manage the scrolling behavior of the document body (<code>document.body</code>) when modals, popups, or bottom sheets are open.</p><h2 id="how-it-solves-layout-shift" tabindex="-1">How It Solves Layout Shift <a class="header-anchor" href="#how-it-solves-layout-shift" aria-label="Permalink to “How It Solves Layout Shift”">​</a></h2><p>When a modal or bottom sheet opens, scrolling on the main page is typically locked (<code>overflow: hidden</code>). In many desktop browsers, hiding the vertical scrollbar causes the page content to abruptly shift to the right (Layout Shift).</p><p><code>ScrollbarManager</code> solves this by calculating the exact width of the user&#39;s browser scrollbar and injecting appropriate CSS custom properties (variables) and padding, smoothly preventing layout jumps.</p><h2 id="core-api-methods" tabindex="-1">Core API Methods <a class="header-anchor" href="#core-api-methods" aria-label="Permalink to “Core API Methods”">​</a></h2><h3 id="_1-add-id" tabindex="-1">1. <code>add(id)</code> <a class="header-anchor" href="#_1-add-id" aria-label="Permalink to “1. add(id)”">​</a></h3><p>Registers a scroll lock for a specific identifier (<code>id</code>). If this is the first active lock, body scrolling is disabled and intelligent padding compensation is applied.</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>import { ScrollbarManager } from &#39;bottom-sheet-manager&#39;;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>const scrollbar = new ScrollbarManager();</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// Lock body scrolling for a custom modal</span></span>
<span class="line"><span>scrollbar.add(&#39;my-custom-modal&#39;);</span></span></code></pre></div><hr><h3 id="_2-remove-id" tabindex="-1">2. <code>remove(id)</code> <a class="header-anchor" href="#_2-remove-id" aria-label="Permalink to “2. remove(id)”">​</a></h3><p>Removes the scroll lock for the specified <code>id</code>. Once all registered locks are removed, body scrolling and layout padding are automatically restored to their original state.</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>// Unlock body scrolling</span></span>
<span class="line"><span>scrollbar.remove(&#39;my-custom-modal&#39;);</span></span></code></pre></div><hr><h3 id="_3-toggle-id" tabindex="-1">3. <code>toggle(id)</code> <a class="header-anchor" href="#_3-toggle-id" aria-label="Permalink to “3. toggle(id)”">​</a></h3><p>Toggles the scroll lock state for a given <code>id</code> (adds the lock if absent, or removes it if present).</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>scrollbar.toggle(&#39;my-custom-modal&#39;);</span></span></code></pre></div><h2 id="css-variables-styling" tabindex="-1">CSS Variables &amp; Styling <a class="header-anchor" href="#css-variables-styling" aria-label="Permalink to “CSS Variables &amp; Styling”">​</a></h2><p>When body scrolling is locked, the <code>.full-width</code> class is added to the <code>&lt;body&gt;</code> element, and the following CSS custom property is injected onto the root (<code>:root</code>):</p><ul><li><code>--scroll-bar-padding</code>: The dynamically calculated width of the browser&#39;s scrollbar (e.g., <code>17px</code>).</li></ul><h3 id="example-css-usage-for-fixed-or-sticky-elements" tabindex="-1">Example CSS Usage for Fixed or Sticky Elements <a class="header-anchor" href="#example-css-usage-for-fixed-or-sticky-elements" aria-label="Permalink to “Example CSS Usage for Fixed or Sticky Elements”">​</a></h3><p>If your page contains fixed (<code>position: fixed</code>) or sticky elements (such as headers or floating action buttons), you can prevent them from shifting by using the injected CSS variable:</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/* Prevent fixed/sticky header layout shift when scroll is locked */</span></span>
<span class="line"><span>body.full-width .fixed-header {</span></span>
<span class="line"><span>  padding-right: var(--scroll-bar-padding);</span></span>
<span class="line"><span>}</span></span></code></pre></div>`,23)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};